if (i >= 0) // 这个条件永远为真
{
    //…
}

var items = new List<object>();

if (items.Count < 0) // 这个条件永远为假
{
    //…
}

x == double.NaN // NaN比较总是为假
'''

## 正确示例
'''csharp
uint i = GetInteger();

if (i > 10) // 根据上下文可能为真或假
{
    //…
}

var items = new List<object>();

if (items.Count > 0) // 正确的条件判断
{
    //…
}

double x = GetValue();
if (double.IsNaN(x)) // 使用正确的方法检测NaN
{
    //…
}
'''

